-- 117: Original BrillaPrep WASSCE Agricultural Science beta questions, part 4.
-- Curriculum-aligned practice content; not official WAEC or NaCCA examination material.
PRAGMA foreign_keys = ON;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_agric_b001_031', 'topic_was_agric_4_1', 'subj_wassce_agric', 'exam_wassce', 'Why should a farm analyse rainfall records across many years?', 'multiple_choice', '["A. To predict an exact storm time years ahead","B. To remove all uncertainty from farming","C. To estimate variability and the likelihood of dry or wet periods","D. To replace current weather forecasts"]', 'C', 'Long records reveal onset, totals, distribution and extremes. They support risk planning, but forecasts and field observations are still needed for current decisions. Therefore the correct answer is C: To estimate variability and the likelihood of dry or wet periods.', 'easy', 1, 1, 90, 'st_was_agric_4_1', 'Explain', 'AO1', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_agric_b001_032', 'topic_was_agric_4_1', 'subj_wassce_agric', 'exam_wassce', 'Warmer conditions allow a crop pest to complete more generations in a season. What is the likely farm effect?', 'multiple_choice', '["A. The pest must become harmless","B. Crop resistance automatically doubles","C. Temperature can no longer affect insect development","D. Pest pressure may increase unless monitoring and control adapt"]', 'D', 'Many insects develop faster within a suitable temperature range. More generations can raise population pressure, so surveillance and integrated management may need adjustment. Therefore the correct answer is D: Pest pressure may increase unless monitoring and control adapt.', 'medium', 2, 2, 90, 'st_was_agric_4_1', 'Identify', 'AO2', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_agric_b001_033', 'topic_was_agric_4_2', 'subj_wassce_agric', 'exam_wassce', 'Which is an adaptation to increasing dry-season water shortages?', 'multiple_choice', '["A. Harvesting rainwater and using efficient irrigation","B. Burning crop residues after every harvest","C. Removing all soil cover","D. Increasing water losses from leaking pipes"]', 'A', 'Water storage increases availability, while efficient delivery reduces losses. Together they lower vulnerability without claiming to prevent drought itself. Therefore the correct answer is A: Harvesting rainwater and using efficient irrigation.', 'hard', 1, 1, 90, 'st_was_agric_4_2', 'Identify', 'AO3', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_agric_b001_034', 'topic_was_agric_4_2', 'subj_wassce_agric', 'exam_wassce', 'Why might a farmer adjust planting date using a credible seasonal forecast?', 'multiple_choice', '["A. To guarantee that the forecast cannot be wrong","B. To better align sensitive crop stages with expected rainfall","C. To remove the need for seed selection","D. To make soil preparation irrelevant"]', 'B', 'Forecasts provide probabilistic guidance rather than certainty. Combining them with local observations, suitable varieties and contingency plans improves the decision. Therefore the correct answer is B: To better align sensitive crop stages with expected rainfall.', 'easy', 2, 2, 90, 'st_was_agric_4_2', 'Explain', 'AO1', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_agric_b001_035', 'topic_was_agric_4_2', 'subj_wassce_agric', 'exam_wassce', 'How can drought-tolerant varieties support climate adaptation?', 'multiple_choice', '["A. They grow without any water","B. They eliminate every crop disease","C. They can maintain useful production under limited water better than susceptible varieties","D. They make good agronomy unnecessary"]', 'C', 'Tolerance reduces yield loss under defined stress conditions, but performance still depends on suitable soils, planting time, nutrients, pests and available moisture. Therefore the correct answer is C: They can maintain useful production under limited water better than susceptible varieties.', 'medium', 3, 3, 90, 'st_was_agric_4_2', 'Explain', 'AO2', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_agric_b001_036', 'topic_was_agric_4_2', 'subj_wassce_agric', 'exam_wassce', 'What adaptation benefit can agroforestry provide on a farm?', 'multiple_choice', '["A. Trees always increase competition without benefits","B. It removes all need for crop management","C. It guarantees identical yields every season","D. Trees can moderate microclimate, protect soil and diversify products"]', 'D', 'Well-designed tree–crop systems can supply shade, wind protection, organic matter and additional products. Species, spacing and management determine whether benefits exceed competition. Therefore the correct answer is D: Trees can moderate microclimate, protect soil and diversify products.', 'hard', 2, 2, 90, 'st_was_agric_4_2', 'Identify', 'AO3', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_agric_b001_037', 'topic_was_agric_4_3', 'subj_wassce_agric', 'exam_wassce', 'Which practice can increase carbon stored in agricultural soil?', 'multiple_choice', '["A. Returning compost and maintaining protective organic matter","B. Burning residues openly","C. Leaving soil bare throughout the year","D. Removing every root after harvest"]', 'A', 'Organic inputs and ground cover can build soil carbon when additions exceed losses. They may also improve structure and water retention under appropriate management. Therefore the correct answer is A: Returning compost and maintaining protective organic matter.', 'easy', 1, 1, 90, 'st_was_agric_4_3', 'Identify', 'AO1', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_agric_b001_038', 'topic_was_agric_4_3', 'subj_wassce_agric', 'exam_wassce', 'Why does avoiding open burning of crop residues help climate mitigation?', 'multiple_choice', '["A. It causes carbon dioxide to disappear from the atmosphere","B. It reduces immediate greenhouse-gas and smoke emissions while preserving material for other uses","C. It stops all decomposition permanently","D. It guarantees zero emissions from farming"]', 'B', 'Open burning rapidly releases carbon and air pollutants. Residues may instead be composted, mulched or otherwise managed according to pest and soil conditions. Therefore the correct answer is B: It reduces immediate greenhouse-gas and smoke emissions while preserving material for other uses.', 'medium', 2, 2, 90, 'st_was_agric_4_3', 'Explain', 'AO2', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_agric_b001_039', 'topic_was_agric_4_3', 'subj_wassce_agric', 'exam_wassce', 'How can applying nitrogen fertiliser at the correct rate and time reduce emissions?', 'multiple_choice', '["A. It makes nitrogen chemically inactive forever","B. It requires applying the whole annual rate during heavy rain","C. It improves crop uptake and reduces excess nitrogen available for loss","D. It removes the need to assess soil fertility"]', 'C', 'Matching application to crop demand improves nitrogen-use efficiency. Avoiding unnecessary or poorly timed inputs can reduce nitrous oxide and leaching losses. Therefore the correct answer is C: It improves crop uptake and reduces excess nitrogen available for loss.', 'hard', 1, 1, 90, 'st_was_agric_4_3', 'Explain', 'AO3', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_agric_b001_040', 'topic_was_agric_4_3', 'subj_wassce_agric', 'exam_wassce', 'Which change can reduce fossil-fuel use for pumping irrigation water?', 'multiple_choice', '["A. Running an oversized diesel pump continuously","B. Allowing distribution pipes to leak","C. Pumping water when storage is already full","D. Using an appropriately sized solar-powered pump with efficient water delivery"]', 'D', 'A correctly designed solar system can replace fuel use during operation. Efficiency, maintenance, storage and responsible groundwater abstraction are still necessary. Therefore the correct answer is D: Using an appropriately sized solar-powered pump with efficient water delivery.', 'easy', 3, 3, 90, 'st_was_agric_4_3', 'Identify', 'AO1', 'board_waec');
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'wassce-agric-beta-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to Ghana’s published NaCCA Agricultural Science curriculum; not official WAEC or NaCCA examination material.', 'https://nacca.gov.gh/wp-content/uploads/2025/04/Agricultural-Science-Curriculum.pdf', 0, 1 FROM questions WHERE id BETWEEN 'q_was_agric_b001_031' AND 'q_was_agric_b001_040';
